}

/**
 * The figures of a sheet's descendants added up: their people, due-totals and overdue-totals; per grade, the due-totals
 * of the people on it not retired; and per status, how many claims have it.
 */
interface DescendantFigures {
  people: number;
  dueTotal: string;
  overdueTotal: string;
  gradeDueTotals: Record<string, string>;
  statusCounts: Record<string, number>;
  members: TreeMember[];
}

/** A person of a sheet as that sheet shows them: due-total, overdue-total, and name and aliases as names are compared. */
interface TreeMember {
  dueTotal: string;
  overdueTotal: string;
  names: string[];
}

/** How many people the members are, those whose names or aliases match (as names are compared) being one. */
function distinctPeople(members: TreeMember[]): number {
  const parent = members.map((_, i) => i);
  const top = (i: number): number => (parent[i] === i ? i : top(parent[i]));
  const firstWith = new Map<string, number>();
  let count = members.length;
  members.forEach((m, i) => {
    for (const name of m.names) {
      const other = firstWith.get(name);
      if (other === undefined) {
        firstWith.set(name, i);
        continue;
      }
      const a = top(i);
      const b = top(other);
      if (a !== b) {
        parent[a] = b;
        count--;
      }
    }
  });
  return count;
}

/** A name as names are compared: trimmed, ignoring case. */
function nameKey(name: string): string {
  return name.trim().toLowerCase();
}

type SortKey = 'added' | 'name' | 'grade' | 'due-total';

function compareKeys(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

const NO_DESCENDANTS: DescendantFigures = {
  people: 0,
  dueTotal: '0.00',
  overdueTotal: '0.00',
  gradeDueTotals: {},
  statusCounts: {},
  members: [],
};

/** What decides which of a person's open claims leave the live totals: their retirement date (a hold does not). */
type LeftOutBy = Pick<Person, 'retiredFrom'>;

/**
 * Whether an open claim of the person, not bound by a statement, is left out of the live totals: any once their
    // The rates fall back on the parent sheet's: once it is read or changed, read them again.
    effect(() => {
      const parent = this.session.parent();
      untracked(() => {
        const sheet = this.session.sheet();
        if (parent !== null && sheet) void this.read(sheet);
      });
    });
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loaded();
      untracked(() => {
        this.people.set([]);
        this.claims.set([]);
        this.rates.set([]);
        this.periods.set([]);
        this.tags.set([]);
        this.descendantFigures.set(NO_DESCENDANTS);
        this.retireDates.set({});
        this.inlineGrades.set({});
        this.aliasInputs.set({});
        this.mergeChoices.set({});
        this.transferTos.set({});
        this.statementAsOfs.set({});
        this.holdFroms.set({});
        this.holdTos.set({});
        this.flagReasons.set({});
        this.flagUntils.set({});
        this.approvers.set({});
        this.patronChoices.set({});
        this.patronError.set(null);
    );
    this.download(lines, `statement-${this.session.sheet() ?? 'sheet'}-${person.id}.csv`);
  }

  /** Save the lines of fields as a CSV file of the name, each line ended by a line feed. */
  private download(lines: string[][], name: string): void {
    const text = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = name;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  /** Re-read the sheet and show the stored values of the person in the open editor. */
  private async reloadEditor(sheet: string, id: number): Promise<void> {
    await this.read(sheet);
    const person = this.people().find((p) => p.id === id);
    if (person && this.editing() === id && this.session.sheet() === sheet) {
      this.editingVersion = person.version;
      this.name.set(person.name);
      this.grade.set(this.gradeOf(person));
      this.terms.set(person.undatedTerms === null ? '' : String(person.undatedTerms));
    this.contact.set(person.contact ?? '');
      this.personTags.set(this.personTagsOf(person).join(', '));
    }
  }

  private async read(sheet: string): Promise<void> {
    const read = ++this.reads;
    const load = this.session.loaded();
    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
    const [list, claims, rates, periods, tags, descendants] = await Promise.all([
      firstValueFrom(this.http.get<Person[]>(`${url}/people`, this.session.headers())),
      firstValueFrom(this.http.get<Claim[]>(`${url}/claims`, this.session.headers())),
      firstValueFrom(this.http.get<Rate[]>(`${url}/rates`, this.session.headers())),
      firstValueFrom(this.http.get<Period[]>(`${url}/periods`, this.session.headers())),
      firstValueFrom(this.http.get<string[]>(`${url}/claims/tags`, this.session.headers())),
      firstValueFrom(this.http.get<DescendantFigures>(`${url}/descendants/figures`, this.session.headers())),
    ]).catch(() => [null, null, null, null, null, null]);
    // A later read wins over a slower earlier one.
    if (list && claims && rates && periods && tags && descendants && read === this.reads && this.session.sheet() === sheet) {
      this.people.set(list);
      this.claims.set(claims);
      this.rates.set(rates);
      this.periods.set(periods);
      this.tags.set(tags);
      this.descendantFigures.set(descendants);
      this.session.shown('people', load);
    }
  }
}
